  "how.anom.s": "العدادات، مقارنة بالساعات نفسها في الأسابيع الماضية.",
  "how.bench": "كل صف طاقة نظام هذا الشهر مقارنة بتصميمه. والشريط الأطول من خطه يعني أنه يستهلك أكثر من التصميم.",
