  "how.fcst": "الخط المتصل هو الطاقة المستهلكة حتى الآن؛ والخط المتقطع هو التوقع مع نطاقه المرجّح مظلّلًا. والخط المدرّج هو الميزانية.",
  "how.fcst.q": "أين ينتهي هذا الشهر والشهر القادم مقارنة بميزانيتيهما، وهل تبقى الذروة دون العقد.",
