  "how.fcst.s": "الأيام نفسها من العام الماضي، معدّلة باتجاه آخر 7 أيام؛ ومختبرة على آخر 3 أشهر.",
  "how.utilities": "يعرض النموذج عدادات المياه والغاز. وتعطي البطاقات استهلاك اليوم مقارنة باليوم المعتاد.",
