  "how.assets": "يعرض النموذج المعدّات. اختر عنصرًا لرؤية قراءاته وإنذاراته وأوامر عمله.",
  "how.assets.q": "ما المعدّات الموجودة في المبنى، وأين، وفي أي حالة.",
