  "how.heatmap": "كل غرفة ملوّنة حسب المقياس الذي تختاره. والرقم في الغرفة هو العدد الآن وتغيّره خلال الساعة الماضية.",
  "how.heatmap.q": "أي الغرف حارة جدًا أو رطبة أو سيئة التهوية أو مزدحمة الآن.",
  "how.heatmap.c": "مقياس الألوان تحت المخطط: الأزرق منخفض والأحمر مرتفع للمقياس الذي اخترته.",
  "how.heatmap.n": "افتح غرفة حمراء لرؤية وحدة مناولة الهواء التي تخدمها.",
  "how.heatmap.s": "حساسات الغرف وأعداد الغرف؛ ولا يُتتبَّع أي فرد.",
  "how.spaces-occ": "كل نقطة شخص واحد معدود في غرفة. حرّك الساعة، أو شغّل اليوم، لترى الغرف تمتلئ وتفرغ. ويعرض استخدام المساحات ما لا يُستخدم.",
  "how.spaces-occ.q": "أين الأشخاص الآن، وكيف يمتلئ المبنى خلال اليوم، وأي المساحات قلّما تُستخدم.",
  "how.spaces-occ.c": "الغرفة الأغمق فيها أشخاص أكثر؛ والنقطة البيضاء شخص واحد معدود.",
  "how.spaces-occ.n": "راجع المساحات قليلة الاستخدام؛ وخطط للتنظيف والصيانة في الساعات الفارغة.",
