  "e14.site": "كيف يعمل هذا في الموقع",
  "e14.siteHide": "إخفاء كيف يعمل هذا في الموقع",
  "e14.siteT": "كيف يعمل هذا في الموقع، داخل المنشأة",
  "e14.site.land.1.k": "الإنذارات:",
  "e14.site.land.1.v": "تُقرأ من FIN Framework عبر BACnet على شبكة الموقع. يقرأ EKO فقط، ولا يُكتب شيء إلى المنشأة. في هذا العرض تأتي من محرك بيانات المبنى في EKO.",
  "e14.site.land.2.k": "أوامر العمل:",
  "e14.site.land.2.v": "تُقرأ من نظام CMMS في الموقع عبر موصل خادم EKO. في هذا العرض هي أوامر العمل التجريبية من المحرك.",
  "e14.site.land.3.k": "التسليم:",
  "e14.site.land.3.v": "سجل EKO الخاص، يُحفظ على خادم EKO في الموقع ويُقفل عند إرساله. بدون الخادم يبقى في هذا المتصفح، ويذكر الموجز ذلك.",
  "e14.site.land.4.k": "الجملة:",
  "e14.site.land.4.v": "تُبنى برمجيًا من الحقائق؛ النموذج في الموقع يعيد صياغتها فقط، ويرفض حارس الأرقام أي رقم لم تعطه البيانات.",
  "e14.site.land.5.k": "الإقرار:",
  "e14.site.land.5.v": "يُسجَّل في EKO باسمك والوقت. أما إرساله إلى FIN أيضًا فقرار الموقع، ولا يزال مفتوحًا.",
  "e14.site.land.6.k": "توهج الذكاء الاصطناعي:",
  "e14.site.land.6.v": "يظهر فقط على النص الذي كتبه النموذج في الموقع؛ والنص المبني من القالب يُعلَّم بكلمة قالب.",
  "e14.site.pred.1.k": "النقطة:",
  "e14.site.pred.1.v": "سجل القراءة من FIN (اتجاه نقطة BACnet). في هذا العرض، سجل محرك بيانات المبنى.",
  "e14.site.pred.2.k": "التوقع:",
  "e14.site.pred.2.v": "خط مستقيم يُوفَّق برمجيًا على خادم EKO على آخر 30 يومًا، مع مداه. ليس الذكاء الاصطناعي. لا توفيق موثوق، لا توقع.",
  "e14.site.pred.3.k": "أمر العمل:",
  "e14.site.pred.3.v": "يُقرأ من نظام CMMS في الموقع. يفتحه EKO؛ وإنشاء أمر يتطلب أن يفعّل العميل موصل CMMS في EKO.",
  "e14.site.pred.4.k": "الإثبات:",
  "e14.site.pred.4.v": "سجل FIN قبل وقت إغلاق أمر العمل في نظام CMMS وبعده.",
  "e14.site.prove.1.k": "البيانات:",
  "e14.site.prove.1.v": "يقرأ EKO وقت إغلاق أمر العمل في نظام CMMS وسجل القراءة في FIN، ويقارن الأيام السابقة باللاحقة، برمجيًا على خادم EKO.",
  "e14.site.prove.2.k": "الحكم:",
  "e14.site.prove.2.v": "تعافى فقط عندما يكون التحسن أكبر من عدم اليقين وتبقى القراءة ضمن نطاقها. وإلا يقول تعافى جزئيًا أو لم يتعافَ أو من المبكر الحكم.",
  "e14.site.prove.3.k": "الطقس:",
  "e14.site.prove.3.v": "تُعدَّل فترة ما بعد بنسبة درجات التبريد في الفترتين، كي لا يبدو شهر أبرد كأنه إصلاح. يعلّم العرض هذا بأنه بديل.",
  "e14.site.exec.1.k": "الطاقة:",
  "e14.site.exec.1.v": "عدادات الموقع عبر FIN، تُجمع برمجيًا على خادم EKO. في هذا العرض، محرك بيانات المبنى.",
  "e14.site.exec.2.k": "الميزانية:",
  "e14.site.exec.2.v": "الشهر نفسه من العام الماضي ناقص هدف التوفير، افتراض تجريبي يؤكده العميل.",
  "e14.site.exec.3.k": "التكلفة:",
  "e14.site.exec.3.v": "سجل تعرفة واحد لكل رقم، مؤقت حتى يؤكده العميل. يظهر للمدير التنفيذي ومدير المرافق فقط.",
  "e14.site.exec.4.k": "المخاطر:",
  "e14.site.exec.4.v": "الإنذارات من FIN وأوامر العمل من CMMS والتوقع، مرتبة برمجيًا؛ والذكاء الاصطناعي يشرح فقط.",
  "e14.site.exec.5.k": "التقرير:",
  "e14.site.exec.5.v": "يُنشأ على خادم EKO من الأرقام نفسها، مع التذييل المعتاد. لا يغادر شيء الموقع.",
  "e14.site.asset.1.k": "لوحة البيانات:",
  "e14.site.asset.1.v": "تُقرأ من النموذج (IFC) عند التشغيل، محليًا؛ ولا يُغيَّر النموذج أبدًا. الحقول التي لا يحملها النموذج قيم تجريبية معلّمة بكلمة تجريبي.",
  "e14.site.asset.2.k": "النقاط:",
  "e14.site.asset.2.v": "نقاط FIN عبر BACnet مع اتجاهاتها من سجل FIN. في هذا العرض، محرك بيانات المبنى.",
  "e14.site.asset.3.k": "التشغيل والصيانة:",
  "e14.site.asset.3.v": "المهمة التالية وسجل الخدمة من نظام CMMS في الموقع؛ والمستندات من مستودع مستندات العميل، العناوين فقط في العرض.",
  "e14.site.asset.4.k": "التنبؤ:",
  "e14.site.asset.4.v": "خط مستقيم يُوفَّق برمجيًا على 30 يومًا، مع مداه؛ لا توفيق موثوق، لا توقع.",
  "e14.site.asset.5.k": "قراءة فقط:",
  "e14.site.asset.5.v": "لا يكتب EKO شيئًا إلى المنشأة؛ وفتح أمر عمل يفتح سجل CMMS.",
